1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
22	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
23	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
28	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
29	    @Mapping(target = "bulkSignupWarning", ignore = true)
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Derives an owner's duplicate-detection identity key as
34	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
35	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
36	     * telephone, email or household id contributes the empty string in its position.
37	     */
38	    default String formatIdentityKey(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
43	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
44	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
45	        return telephone + "|" + email + "|" + householdId;
46	    }
47	
48	    /**
49	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
50	     * (non-null and non-blank), otherwise {@code PHONE}.
51	     */
52	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
57	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
58	    }
59	
60	    /**
61	     * Derives an owner's locality (region) from the customer-code identity: it is the {@code REGION}
62	     * segment of the {@code '<REGION>-<HASH8>'} customer code (the part before the first {@code '-'}).
63	     * When the customer code is absent it falls back to resolving the region directly, preferring the
64	     * postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) and then the fixed city-to-region
65	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), yielding
66	     * {@code "UNKNOWN"} when neither resolves.
67	     */
68	    default String formatLocality(Owner owner) {
69	        if (owner == null) {
70	            return null;
71	        }
72	        String code = owner.getCustomerCode();
73	        if (code != null) {
74	            int dash = code.indexOf('-');
75	            if (dash > 0) {
76	                return code.substring(0, dash);
77	            }
78	        }
79	        String fromPostcode = regionForPostcode(owner.getPostcode());
80	        if (fromPostcode != null) {
81	            return fromPostcode;
82	        }
83	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
84	            case "Sydney" -> "NSW";
85	            case "Melbourne" -> "VIC";
86	            case "Brisbane" -> "QLD";
87	            default -> "UNKNOWN";
88	        };
89	    }
90	
91	    /**
92	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
93	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
94	     * no known range, signalling that the caller should fall back to the city-to-region table.
95	     */
96	    private String regionForPostcode(String postcode) {
97	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
98	            return null;
99	        }
100	        int value = Integer.parseInt(postcode);
101	        if (value >= 2000 && value <= 2099) {
102	            return "NSW";
103	        }
104	        if (value >= 3000 && value <= 3099) {
105	            return "VIC";
106	        }
107	        if (value >= 4000 && value <= 4099) {
108	            return "QLD";
109	        }
110	        return null;
111	    }
112	
113	    /**
114	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
115	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
116	     * tenure).
117	     */
118	    default Integer formatMembershipLevel(Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        int level = 1;
123	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
124	        if (hasEmail) {
125	            level++;
126	        }
127	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
128	        if (unique) {
129	            level++;
130	        }
131	        return Math.min(level, 3);
132	    }
133	
134	    /**
135	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
136	     * customer code. Returns {@code null} when the customer code is absent.
137	     */
138	    default Integer formatCheckDigit(Owner owner) {
139	        if (owner == null || owner.getCustomerCode() == null) {
140	            return null;
141	        }
142	        String code = owner.getCustomerCode();
143	        int sum = 0;
144	        boolean dbl = true;
145	        for (int i = code.length() - 1; i >= 0; i--) {
146	            char c = code.charAt(i);
147	            if (c < '0' || c > '9') {
148	                continue;
149	            }
150	            int d = c - '0';
151	            if (dbl) {
152	                d *= 2;
153	                if (d > 9) {
154	                    d -= 9;
155	                }
156	            }
157	            sum += d;
158	            dbl = !dbl;
159	        }
160	        return (10 - (sum % 10)) % 10;
161	    }
162	
163	    /**
164	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
165	     * digits of the registration-date year (e.g. {@code "NSW-1A2B3C4D-M26"}). Returns {@code null} when the
166	     * customer code or registration date is absent.
167	     */
168	    default String formatMembershipNumber(Owner owner) {
169	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
170	            return null;
171	        }
172	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
173	    }
174	
175	    /**
176	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
177	     */
178	    default String formatDisplayName(Owner owner) {
179	        if (owner == null) {
180	            return null;
181	        }
182	        return owner.getLastName() + ", " + owner.getFirstName();
183	    }
184	
185	    /**
186	     * Formats an owner's initials as the upper-cased first letters of the first and last
187	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
188	     */
189	    default String formatInitials(Owner owner) {
190	        if (owner == null) {
191	            return null;
192	        }
193	        return initial(owner.getFirstName()) + initial(owner.getLastName());
194	    }
195	
196	    private String initial(String name) {
197	        if (name == null || name.isEmpty()) {
198	            return "";
199	        }
200	        return Character.toUpperCase(name.charAt(0)) + ".";
201	    }
202	
203	    Owner toOwner(OwnerDto ownerDto);
204	
205	    @Mapping(target = "id", ignore = true)
206	    @Mapping(target = "pets", ignore = true)
207	    Owner toOwner(OwnerFieldsDto ownerDto);
208	
209	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
210	
211	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
212	
213	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
214	        OwnerPageDto ownerPageDto = new OwnerPageDto();
215	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
216	        ownerPageDto.setPage(ownerPage.getNumber());
217	        ownerPageDto.setSize(ownerPage.getSize());
218	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
219	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
220	        return ownerPageDto;
221	    }
222	}
