346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
349	        Collection<Owner> owners;
350	        if (lastName != null) {
351	            owners = this.clinicService.findOwnerByLastName(lastName);
352	        } else {
353	            owners = this.clinicService.findAllOwners();
354	        }
355	        if (owners.isEmpty()) {
356	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
357	        }
358	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
364	        Owner owner = this.clinicService.findOwnerById(ownerId);
365	        if (owner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
369	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
370	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
371	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
377	        String telephone = toE164(ownerFieldsDto.getTelephone());
378	        if (telephone == null) {
379	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
380	        }
381	        String email = ownerFieldsDto.getEmail();
382	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
383	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
384	        }
385	        String address = normaliseAddress(ownerFieldsDto.getAddress());
386	        if (address.isEmpty()) {
387	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
388	        }
389	        String postcode = ownerFieldsDto.getPostcode();
390	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
391	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
392	        }
393	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
394	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
395	        LocalDate registrationDate = toBusinessDay(effectiveDate);
396	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
397	            .map(Owner::getRegistrationDate)
398	            .filter(existing -> existing != null)
399	            .map(OwnerRestControllerV1::toBusinessDay)
400	            .filter(registrationDate::equals)
401	            .count();
402	        if (ownersCreatedThatDay >= 100) {
403	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
404	        }
405	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
406	        long ownersInCity = this.clinicService.findAllOwners().stream()
407	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
408	            .count();
409	        if (ownersInCity >= 50) {
410	            return new ResponseEntity<>(HttpStatus.CONFLICT);
411	        }
412	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
413	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
414	        String addressKey = address;
415	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
416	            .filter(existing ->
417	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
418	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
419	            .toList();
420	        String householdId = (sharesHousehold && !householdMembers.isEmpty())
421	            ? householdId(lastNameKey, addressKey) : null;
422	        String identityKey = identityKey(telephone, email, householdId);
423	        boolean identityInUse = this.clinicService.findAllOwners().stream()
424	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
425	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
426	        if (identityInUse) {
427	            return new ResponseEntity<>(HttpStatus.CONFLICT);
428	        }
429	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
430	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
431	            .filter(existing ->
432	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
433	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
434	            .count();
435	        HttpHeaders headers = new HttpHeaders();
436	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
437	        owner.setNamesakeCount(namesakeCount);
438	        owner.setAddress(address);
439	        owner.setTelephone(telephone);
440	        owner.setEmail(email == null ? null : email.toLowerCase());
441	        owner.setRegistrationDate(registrationDate);
442	        owner.setCustomerCode(nextCustomerCode(
443	            region(postcode, owner.getCity()), telephone, owner.getLastName()));
444	        if (householdId != null) {
445	            owner.setHouseholdId(householdId);
446	            for (Owner member : householdMembers) {
447	                if (member.getHouseholdId() == null) {
448	                    member.setHouseholdId(householdId);
449	                    this.clinicService.saveOwner(member);
450	                }
451	            }
452	        }
453	        this.clinicService.saveOwner(owner);
454	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
455	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
456	            ownerMapper.formatMembershipLevel(owner));
457	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
458	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
459	        headers.setLocation(UriComponentsBuilder.newInstance()
460	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
461	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
462	    }
463	
464	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
465	    @Override
466	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
467	        String telephone = toE164(ownerFieldsDto.getTelephone());
468	        if (telephone == null) {
469	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
470	        }
471	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
472	        if (currentOwner == null) {
473	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
474	        }
475	        String email = ownerFieldsDto.getEmail();
476	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
477	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
478	        }
479	        currentOwner.setAddress(ownerFieldsDto.getAddress());
480	        currentOwner.setCity(ownerFieldsDto.getCity());
481	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
482	        currentOwner.setLastName(ownerFieldsDto.getLastName());
483	        currentOwner.setTelephone(telephone);
484	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
485	        this.clinicService.saveOwner(currentOwner);
486	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
487	    }
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Transactional
491	    @Override
492	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
493	        Owner owner = this.clinicService.findOwnerById(ownerId);
494	        if (owner == null) {
495	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	        }
497	        this.clinicService.deleteOwner(owner);
498	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
504	        Owner owner = this.clinicService.findOwnerById(ownerId);
505	        if (owner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        HttpHeaders headers = new HttpHeaders();
509	        Pet pet = petMapper.toPet(petFieldsDto);
510	        owner.setId(ownerId);
511	        pet.setOwner(owner);
512	        pet.getType().setName(null);
513	        this.clinicService.savePet(pet);
514	        PetDto petDto = petMapper.toPetDto(pet);
515	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
516	            .buildAndExpand(pet.getId()).toUri());
517	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
518	    }
519	
