521	    @Override
522	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
523	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
524	        if (currentOwner != null) {
